{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Lurasidone has an absolute oral bioavailability of 9–19% in humans, below the 20% threshold, providing affirmative low-F evidence with a high assay-transfer score.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Praziquantel showed 27.2% bioavailability in patients with hepatic disease, above the threshold, but it is a neutral lipophilic drug lacking the query's strongly ionizable acidic groups.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Solifenacin has an absolute oral bioavailability of 88% in healthy volunteers, but it is a basic ester/amine drug with no acidic phosphonate/carboxylate, so its high F is not mechanistically transferable to the diacid query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Encainide has a mean oral bioavailability of 32±7% in normal subjects, above threshold, but it is a basic amide/amine without the query's acidic ionizable groups.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Vernakalant has 71±21% oral bioavailability in healthy volunteers, but it is a basic ether/amine, not an acidic phosphonate, limiting mechanistic transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "SAHA (vorinostat) has 43% oral bioavailability in humans, but its hydroxamic acid is weakly acidic and largely neutral at physiological pH, unlike the strongly ionized phosphonic/carboxylic acids of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fosinoprilat, a phosphinic acid/carboxylic acid diacid that will be ionized at physiological pH, severely limiting membrane permeability and oral absorption. The only affirmative low-F evidence (lurasidone, 9–19%) transfers with high score. The numerous high-F analogues lack the acidic ionizable groups and are mechanistically less applicable; their high F does not override the strong physicochemical barrier. Prediction: low.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for fosinoprilat or a close phosphonic acid-containing analogue.",
    "Retrieved high-F evidence lacks the query's strongly acidic phosphonic/carboxylic acid groups, so its transferability is mechanistically limited despite high assay-transfer scores.",
    "Lurasidone's low F is attributed to first-pass metabolism rather than permeability, so it is not a perfect mechanistic match."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

